(() => {
	const fallbackProgram = "your_game.prg";
	const nativeWidth = 768;
	const nativeHeight = 494;
	const canvas = document.querySelector("#canvas");

	if (!canvas || typeof Emulator === "undefined" || typeof VICELoader === "undefined") {
		return;
	}

	const decodeEntities = (value) => {
		const area = document.createElement("textarea");
		area.innerHTML = value;
		return area.value;
	};

	const detectProgram = async () => {
		try {
			const response = await fetch("./", { cache: "no-store" });
			if (!response.ok) {
				return fallbackProgram;
			}

			const html = await response.text();
			const matches = [...html.matchAll(/href=["']([^"']+\.prg)["']/gi)]
				.map((match) => decodeEntities(match[1]))
				.map((entry) => entry.split("?")[0].split("#")[0])
				.map((entry) => {
					try {
						return decodeURIComponent(entry).replace(/^\.\//, "");
					} catch {
						return entry.replace(/^\.\//, "");
					}
				})
				.filter((entry) => entry && !entry.includes("/"));

			return matches[0] || fallbackProgram;
		} catch {
			return fallbackProgram;
		}
	};

	const createInfoOverlay = () => {
		const overlay = document.createElement("div");
		overlay.style.cssText = `
			position: fixed;
			top: 0;
			left: 0;
			width: 100%;
			height: 100%;
			background: rgba(0, 0, 0, 0.85);
			display: flex;
			align-items: center;
			justify-content: center;
			z-index: 9999;
		`;

		const img = document.createElement("img");
		img.src = "splash.png";
		img.style.cssText = `
			max-width: 100%;
			max-height: 100%;
			object-fit: contain;
			cursor: pointer;
		`;

		overlay.appendChild(img);
		document.body.appendChild(overlay);

		return new Promise(resolve => {
			const handler = () => {
				overlay.remove();
				document.removeEventListener("keydown", handler);
				document.removeEventListener("click", handler);
				resolve();
			};
			document.addEventListener("keydown", handler);
			document.addEventListener("click", handler);
		});
	};

	const start = async () => {
		const program = await detectProgram();
		canvas.width = nativeWidth;
		canvas.height = nativeHeight;

		const emulator = new Emulator(
			canvas,
			null,
			new VICELoader(
				VICELoader.emulatorJS("vendor/emularity/vice-resid.js"),
				VICELoader.nativeResolution(nativeWidth, nativeHeight),
				VICELoader.extraArgs([
					"-ntsc",							
					"-joydev2",
					"1",
					"-VICIIfilter",
					"0",
					"-VICIIextpal",
					"-VICIIpalette",
					"community-colors",
					"-soundrate",
					"48000",
					"-soundsync",
					"2",
					"-soundfragsize",
					"4",
					"-soundbufsize",
					"150",
					"-residsamp",
					"0"
				]),
				VICELoader.fliplist([null, null, null, null]),
				VICELoader.mountFile(
					program,
					VICELoader.fetchFile("Program", program)
				),
				VICELoader.autoLoad(program)
			)
		);

		await createInfoOverlay();
		emulator.start({ waitAfterDownloading: false });
		canvas.style.width = `${canvas.width}px`;
		canvas.style.height = `${canvas.height}px`;
	};

	start();
})();
